	public void ChangeJoeyImage()
	{
		StartCoroutine(ChangeJoeyImageCoroutine());
	}

	IEnumerator ChangeJoeyImageCoroutine()
	{
		if (m_DataJoeyPlayer.playerHealth < m_DataJoeyPlayer.lastPlayerHealth)
		{
			m_View.JoeyImage.sprite = sadSprite;
		}
		else if (m_DataJoeyPlayer.playerHealth > m_DataJoeyPlayer.lastPlayerHealth)
		{
			m_View.JoeyImage.sprite = happySprite;
		}
		else if (m_DataJoeyPlayer.playerHealth <= 0)
		{
			m_View.JoeyImage.sprite = deathSprite;
		}
		yield return new WaitForSeconds(0.5f);
		m_View.JoeyImage.sprite = sleepSprite;
	}

	private UICardSimpleControl GetCardSimple(Transform parent)
	{
		for (int i = 0; i < m_CardSimplePool.Count; i++)
		{
			if (!m_CardSimplePool[i].gameObject.activeSelf)
			{
				m_CardSimplePool[i].gameObject.SetActive(true);
				m_CardSimplePool[i].transform.SetParent(parent);
				m_CardSimplePool[i].transform.localScale = Vector3.one;
				return m_CardSimplePool[i];
			}
		}

		UICardSimpleControl cardControl = this.Asset.OpenUI<UICardSimpleControl>(parent);
		m_CardSimplePool.Add(cardControl);
		return cardControl;
	}

	private Card CreateCard(string cardId)
	{
		Card card = GData.Instance.GetCardConfigById(cardId).Clone();
		UniqueIdGen++;
		card.UniqueId = UniqueIdGen;
		m_CardDict[UniqueIdGen] = card;
		return card;
	}

	public void AddCardList(ECardType cardType, List<string> cardIds)
	{
		Debug.Log("AddCardList: " + cardType + " " + cardIds.Count);

		Transform parent = null;
		switch (cardType)
		{
			case ECardType.attack:
				parent = m_View.AttackPanel.transform;
				break;
			case ECardType.defence:
				parent = m_View.DefencePanel.transform;
				break;
			case ECardType.skill:
				parent = m_View.SkillPanel.transform;
				break;
			case ECardType.item:
				parent = m_View.ItemPanel.transform;
				break;
			case ECardType.monster:
			case ECardType.other:
				parent = m_View.EnvPanels.transform;
				break;
			default:
				return;
		}

		for (int i = cardIds.Count - 1; i >= 0; i--)
		{
			string cardId = cardIds[i];
			Card card = CreateCard(cardId);
			UICardSimpleControl cardControl = GetCardSimple(parent);
			cardControl.SetData(card);
			AddBagCard(cardType, cardControl);
		}
	}

	public void AddEnvCardList(List<string> cardIds, int index)
	{
		VerticalLayoutGroup parent = m_EnvPanels[index];

		for (int i = cardIds.Count - 1; i >= 0; i--)
		{
			string cardId = cardIds[i];
			Card card = CreateCard(cardId);
			UICardSimpleControl cardControl = GetCardSimple(parent.transform);
			cardControl.SetData(card, isEnv: true, envIndex: index);
			AddEnvCard(index, cardControl);
		}
	}

	public Card GetCardDataById(int uniqueId)
	{
		return m_CardDict[uniqueId];
	}

	private void AddBagCard(ECardType cardType, UICardSimpleControl cardControl)
	{
		int cardTypeInt = (int)cardType;
		if (!m_BagCardDict.ContainsKey(cardTypeInt))
		{
			m_BagCardDict[cardTypeInt] = new List<UICardSimpleControl>();
		}
		m_BagCardDict[cardTypeInt].Add(cardControl);
		cardControl.transform.localScale = new Vector3(0.8f, 0.8f, 0.8f);
	}

	private void RemoveBagCard(ECardType cardType, UICardSimpleControl cardControl)
	{
		int cardTypeInt = (int)cardType;
		if (m_BagCardDict.ContainsKey(cardTypeInt))
		{
			m_BagCardDict[cardTypeInt].Remove(cardControl);
			RemoveCardData(cardControl.CardData.UniqueId);
			cardControl.Return();

			UICardSimpleControl newLastBagCard = GetLastBagCard(cardType);
			if (newLastBagCard != null)
			{
				newLastBagCard.CardEffect?.OnBecomeTopOfPile();
			}
		}
	}

	private List<UICardSimpleControl> GetBagCardList(ECardType cardType)
	{
		int cardTypeInt = (int)cardType;
		if (m_BagCardDict.ContainsKey(cardTypeInt))
		{
			return m_BagCardDict[cardTypeInt];
		}
		return null;
	}

	private UICardSimpleControl GetLastBagCard(ECardType cardType)
	{
		List<UICardSimpleControl> cardList = GetBagCardList(cardType);
		if (cardList != null && cardList.Count > 0)
		{
			return cardList[cardList.Count - 1];
		}
		return null;
	}

	private void AddEnvCard(int index, UICardSimpleControl cardControl)
	{
		if (!m_EnvCardDict.ContainsKey(index))
		{
			m_EnvCardDict[index] = new List<UICardSimpleControl>();
		}
		m_EnvCardDict[index].Add(cardControl);
	}

	private void RemoveEnvCard(int index, UICardSimpleControl cardControl)
	{
		if (m_EnvCardDict.ContainsKey(index))
		{
			m_EnvCardDict[index].Remove(cardControl);
			RemoveCardData(cardControl.CardData.UniqueId);
			cardControl.Return();
		}
	}

	void RemoveCardData(int uniqueId)
	{
		if (m_CardDict.ContainsKey(uniqueId))
		{
			Card card = m_CardDict[uniqueId];
			UsedCardList.Add(card);
			m_CardDict.Remove(uniqueId);
		}
	}

	public void ClearAllCard()
	{
		for (int i = 0; i < m_CardSimplePool.Count; i++)
		{
			if (m_CardSimplePool[i] != null && m_CardSimplePool[i].gameObject.activeSelf)
			{
				m_CardSimplePool[i].Return();
			}
		}

		m_CardDict.Clear();
		m_EnvCardDict.Clear();
		m_BagCardDict.Clear();
		UsedCardList.Clear();
		UniqueIdGen = 0;
	}

	void MoveCard(object[] paraArray)
	{
		bool isEnv = (bool)paraArray[0];
		UICardSimpleControl cardControl = (UICardSimpleControl)paraArray[1];

		if (isEnv)
		{
			ECardType cardType = cardControl.CardType;
			AddBagCard(cardType, cardControl);
			cardControl.CardEffect?.OnEnterBag();

			Transform parent = null;
			switch (cardType)
			{
				case ECardType.attack:
					parent = m_View.AttackPanel.transform;
					break;
				case ECardType.defence:
					parent = m_View.DefencePanel.transform;
					break;
				case ECardType.skill:
					parent = m_View.SkillPanel.transform;
					break;
				case ECardType.item:
					parent = m_View.ItemPanel.transform;
					break;
				default:
					return;
			}
			cardControl.transform.SetParent(parent);
		}
	}

	void TakeEnemyDamage(object[] paraArray)
	{
		UICardSimpleControl enemyCardControl = (UICardSimpleControl)paraArray[0];
		int attackCount = (int)paraArray[1];
		int envIndex = (int)paraArray[2];
		UICardSimpleControl attackCardControl = GetLastBagCard(ECardType.attack);
		Card attackCard = attackCardControl.CardData;
		int damage = attackCard.currentAttack;
		for (int i = 0; i < attackCount; i++)
		{
			attackCardControl.CardEffect?.OnDealDamage();
			enemyCardControl.CallCardTakeDamage(damage);
			enemyCardControl.CardEffect?.OnTakeDamage();

			if (enemyCardControl.CardData.currentHealth <= 0)
			{
				attackCardControl.CardEffect?.OnKill();
				enemyCardControl.CardEffect?.OnDead();
				RemoveEnvCard(envIndex, enemyCardControl);
				break;
			}
			else
			{
				int enemyAttack = enemyCardControl.CardData.currentAttack;
				YActionSystem.Instance.DispatchAction(EActionId.TakePlayerDamage, enemyAttack);
			}
		}
		RemoveBagCard(ECardType.attack, attackCardControl);
	}

	void TakePlayerDamage(object[] paraArray)
	{
		int enemyAttack = (int)paraArray[0];
		int defenceValue = 0;
		UICardSimpleControl defenceCardControl = GetLastBagCard(ECardType.defence);
		if (defenceCardControl != null)
		{
			defenceValue = defenceCardControl.CardData.currentDefence;
		}
		int damage = 0;
		if (defenceValue < enemyAttack)
		{
			damage = enemyAttack - defenceValue;
		}
		m_DataJoeyPlayer.playerHealth -= damage;
		if (m_DataJoeyPlayer.playerHealth < 0)
		{
			m_DataJoeyPlayer.playerHealth = 0;
		}
		OnHPChanged(m_DataJoeyPlayer.playerHealth);
		OnAttackChanged(m_DataJoeyPlayer.playerAttack);
		OnDefenceChanged(m_DataJoeyPlayer.playerDefence);

		if (defenceCardControl != null)
		{
			RemoveBagCard(ECardType.defence, defenceCardControl);
		}

		if (m_DataJoeyPlayer.playerHealth <= 0)
		{
			if (m_GameOverControl == null)
			{
				m_GameOverControl = this.Asset.OpenUI<UIGameOverControl>();
			}
			else
			{
				m_GameOverControl.gameObject.SetActive(true);
			}
		}
	}

	protected override void OnReturn()
	{
		base.OnReturn();
	}
